if (dayInWeek <= 3) {
   if (completedReps >= reps) { 
    if (state.repscheme != 8) {
      state.repscheme = state.repscheme - 2}
    else {
      state.repscheme = 12}
}}

if (dayInWeek >= 4) {
  if (completedReps[1] != state.myorep){
    state.myorep = completedReps[1]}
  if (completedReps[1] >= 25){
    state.myorep = 15}}

if (calculate1RM(w[1], completedReps[1]) >= rm1 ){
rm1 = calculate1RM(w[1], completedReps[1])
}
if (calculate1RM(w[2], completedReps[2]) >= rm1 ){
rm1 = calculate1RM(w[2], completedReps[2])
}
if (calculate1RM(w[3], completedReps[3]) >= rm1 ){
rm1 = calculate1RM(w[3], completedReps[3])
}
