rm1 = calculate1RM(w[ns], completedReps[ns])
}
if (calculate1RM(w[ns-1], completedReps[ns-1]) >= rm1 ){
rm1 = calculate1RM(w[ns-1], completedReps[ns-1])
}
if (calculate1RM(w[ns-2], completedReps[ns-2]) >= rm1 ){
rm1 = calculate1RM(w[ns-2], completedReps[ns-2])
}

if (completedReps[1] >= state.myorep){
  state.myorep = completedReps[1] + 1}
if (completedReps[1] >= 25){
  rm1 = rm1 + 5
