                  var.minReps = var.set == 2 && state.type == var.TYPE_UNILATERAL ? state.targetMinReps : var.MIN_HYP_REPS
                  var.reps = state.targetMaxReps
                }
              }
              else {
                var.reps = var.reps + 1
              }            
            }
          }

          var.weight = var.weight >= 0lb ? var.weight : 0lb

          /// Override default values set earlier so we can match/beat performance
          if (var.incrementModifier == 1) {
            if (completedWeights[var.set] != completedWeights[1]) {
              weights[var.set] = roundWeight(var.weight)
            }
            minReps[var.set] = var.minReps
            reps[var.set] = var.reps
          }

          /// Only set potentially different weight for a deload set if we are still
          /// using heavy weight for deload week. Otherwise, we'll just keep using the
          /// same weight from set 1 for all deload to avoid having to change weights.
          var.todaysWeight = state.deloadWeightRatio >= var.DELOAD_WEIGHT_RATIO_HEAVY ?
            completedWeights[var.set] : completedWeights[1]
        }

        /// Update deload week based on todays performance in case we deload early. We
        /// update the value for all days rather than just this day of the week since
        /// some exercises may change days during deloads
        weights[var.DELOAD_WEEK:*:*:*] = roundWeight(var.todaysWeight * state.deloadWeightRatio)
        minReps[var.DELOAD_WEEK:*:*:var.set] = floor(var.todaysReps * state.deloadRepsRatio)
        reps[var.DELOAD_WEEK:*:*:var.set] = floor(var.todaysReps * state.deloadRepsRatio)
      }
    }

    /// Ensure sets modifier is 0 so we don't add sets. Must be done before processing the
    /// rating since you may be rating this same exercise.
    state.setsModifier = 0

    if (state.progressType != var.PROG_TYPE_NONE) {
      if (var.progressDay) {
        state.numSets = numberOfSets/state.type
      }
      /// Do set progression if rating and target exercise values are set
      if (state.rating != 0 && state.rateGroup != 0 && state.numRatingExercises != 0) {
        /// Combine group + index to create full unique tag
        var.tag = state.rateGroup*100 + state.ratingIndex
        state[var.tag].setsModifier = state.rating
        state.ratingIndex = (state.ratingIndex + 1) % state.numRatingExercises
      }
    }

    /// RPE target for next session
    var.nextRpe = var.progressDay ? state.targetRpe + var.RPE_INCR : state.targetRpe
    var.nextRpe = var.nextRpe <= var.RPE_END ? var.nextRpe : var.RPE_END
    var.nextRpe = var.nextRpe >= var.RPE_START ? var.nextRpe : var.RPE_START
    state.targetRpe = var.nextRpe

    /// Calculate weight to start week 1 of next meso based on weight achieved today
    /// since we could deload early or do recovery weeks or whatnot and restart a meso
    /// at any time.
    /// Logic here just ensures the weight we pick keeps us in the target rep range
    /// for week 1 of the meso based on the last non-recovery weight and RIR/RPE we
    /// did.
    if (var.progressDay && var.hitReps == 1) {      
      /// RIR value where we want to start the meso
      var.startRir = 10 - floor(var.RPE_START)
      /// Based on RPE of set 1 today we can convert to how many reps-in-reserve
      var.rir = 10 - ceil(RPE[1] > 0 ? RPE[1] : state.targetRpe)
      /// Calculate an estimate for maximum number of reps possible at todays weight.
      /// Add 1 rep to assume we adapt and get a little stronger after this session.
      /// i.e. Estimate how many reps would be 0 RIR or failure with todays weight
      var.estMaxRepsAfterRecovering = completedReps[1] + var.rir + 1

      /// Determine estimate for how many reps would correspond to the starting RIR
      /// i.e. how many reps would be the target given the RIR we want to start at
      var.startRepEstimate = var.estMaxRepsAfterRecovering - var.startRir

      /// Next, based on how many starting reps we estimated, determine how many
      /// increments to modify the weight to keep us within our target rep range
      /// for week 1 set 1.
      var.numIncrements = 0

      /// If estimated reps for a starting RIR set with todays weight would be higher
      /// than the target rep range we can increase weight by 1 increment for every rep
      /// above the target max since we assume that every increment drops about 1 rep
      /// worth of strength
      if (var.startRepEstimate >= state.targetMaxReps) {
        /// + 1 to ensure we land more inside in the target range and not exactly
        /// at the max reps
        var.numIncrements = (var.startRepEstimate - state.targetMaxReps) + 1
      }
      /// Otherwise, if starting RIR would be below the minimum reps we need to decrease the
      /// weight to ensure we get more reps next time to put us in the target rep range
      /// (numIncrements will be negative)
      else if (var.startRepEstimate <= state.targetMinReps) {
        /// - 1 to ensure we land more inside in the target range and not exactly
        /// at the min reps
        var.numIncrements = (var.startRepEstimate - state.targetMinReps) - 1
      }

      /// Set starting weight for next meso
      var.weight = roundWeight(completedWeights[1] + var.numIncrements*state.increment)
      weights[1:*:*:*] = var.weight >= 0lb ? var.weight : 0lb
    }

    state.mesoWeek += 1
  }
  /// Deload week is done, so reset start of meso targets
  else {
    state.mesoWeek = 1
    state.lastIncrement = 0lb
    state.ratingIndex = 0
    state.numSets = state.startNumSets
    state.setsModifier = 0
    state.targetRpe = var.RPE_START
  }

  /// Always ensure default state of keeping sets the same for related target exercise(s)
  state.rating = 0
  RPE[var.DELOAD_WEEK:*:*:*] = var.RPE_RECOVERY

~}

