///***Muscle Group IDs***/
/// 01 => Chest
/// 02 => Triceps
/// 03 => Back
/// 04 => Biceps
/// 05 => Calves
/// 06 => Quads & Glutes
/// 07 => Hamstrings
/// 08 => Side Delts
/// 09 => Abs

/// Full tag is created by combining digits from:
/// Day (1-2 digits) & Muscle Group ID (2-digits) & Index (2 digits, 0-based)
/// to create 5-6 digit long unique tag.
///
/// Ex:
/// 3 Quads exercises on day 4 would have tags:
/// 40600, 40601, 40602
/// 4 => 4th day of week
/// 06 => Quads Muscle Group ID
/// 00, 01, 02 => Index of exercise for muscle group in that day

///*****PROGRAM LOGIC*****///
tLogic: Squat[1-3] / used: none / 10+x5 / 86.53% / warmup: 1x12 50%, 1x8 75%, 1x4 110% / update: custom() {~
  /// Minimum reps for any set to be in the hypertrophy range (based on RP
  /// guidelines of about 5-30 reps between 3-0 RIR for hypertrophy as of
  /// early 2024)
  var.MIN_HYP_REPS = 5

  /// Bilateral exercise (both sides at the same time)
  var.TYPE_BILATERAL = 1
  /// Unilateral exercise (left/right side done as separate sets)
  var.TYPE_UNILATERAL = 2

  /// Minimum increment value that will be treated as a fixed weight rather than percentage
  var.FIXED_WEIGHT_INCR_MIN = 0.25

  /// Disable progression and match or beat system, just repeat targets
  var.PROG_TYPE_NONE = 0
  /// Linear - Add weight each week keeping a fixed single rep target after
  /// week 1, unless at the minimum for hypertrophy, in that case add 1 rep.
  var.PROG_TYPE_WEIGHT = 1
  /// Double - Add reps until hitting the top of the target rep range, then
  /// add weight and reset rep targets to the original range
  var.PROG_TYPE_REPS = 2

  /// Number of expected accumulation weeks to estimate RPE/RIR progression
  var.ACCUM_WEEKS = 4
  /// Week number to determine when progression vs deload logic applies (should
  /// be last week number defined in program)
  var.DELOAD_WEEK = 3

  /// Target RPE for week 1 of the program
  var.RPE_START = 7
  /// Target RPE for final accumulation week
  var.RPE_END = 10
  /// How much RPE should increase each week to reach RPE_END by final accumulation week
  var.RPE_INCR = (var.RPE_END-var.RPE_START)/(var.ACCUM_WEEKS-1)
  /// RPE value for deload and triggers recovery session logic to update all sets in that session
  var.RPE_RECOVERY = 3

  /// Prepare workout and handle set progression
  if (setIndex == 0) {
    /// Always start mesocycle with defined number of sets and values
    if (week == 1) {
      numberOfSets = state.startNumSets*state.type
      /// Make all sets AMRAP during week 1 since we're targetting a rep range & RIR, keeping all other values the same
      sets(1, state.type, state.targetMinReps, state.targetMaxReps, 1, completedWeights[1], 0, var.RPE_START, 0)
      sets(state.type+1, numberOfSets, var.MIN_HYP_REPS, var.MIN_HYP_REPS, 1, completedWeights[1], 0, var.RPE_START, 0)
    }
    /// Only do set progression during accumulation weeks
    else if (week < var.DELOAD_WEEK) {
      var.numSets = state.numSets
      if (state.progressType != var.PROG_TYPE_NONE) {
        var.numSets = (state.numSets + state.setsModifier)*state.type /// Double for unilateral exercises
        var.numSets = var.numSets >= 0 ? var.numSets : 0
      }      
      numberOfSets = var.numSets

      var.rpe = 0
      var.amrap = 0
      /// Check if sets were added since last time
      if (numberOfSets/state.type > state.numSets) {
        /// Offset RPE by 1 increment since sets have increased and we don't want to progress sets & proximity
        /// to failure at the same time per critiques of RP methodolgy from sources like Eric Helms and MASS
        var.rpe = state.targetRpe - var.RPE_INCR
        var.rpe = var.rpe >= var.RPE_START ? var.rpe : var.RPE_START
        var.amrap = 1

        /// Undo previous weight progression when adding sets and doing linear progression so multiple variables
        /// are not progressing at once. Only reverse if we increased by a single increment over last time.
        if (state.progressType == var.PROG_TYPE_WEIGHT) {
          /// Handle reversing fixed increments
          if (state.increment >= var.FIXED_WEIGHT_INCR_MIN) {
            if (state.lastIncrement == state.increment) {
              weights -= state.lastIncrement
            }
          }
          /// Handle reversing percentage based increments
          else if (state.increment > 0) {
            var.lastWeight = completedWeights[1] - state.lastIncrement
            var.lastWeightIncremented = roundWeight(var.lastWeight + (var.lastWeight*state.increment))
            if (var.lastWeightIncremented == completedWeights[1]) {
              weights -= state.lastIncrement
            }
          }
        }

