  /// pretty heavy, and working weights bewteen sets were different during
  /// accumulation, we probably also want to use different weights in each deload
  /// set.
  var.DELOAD_WEIGHT_RATIO_HEAVY = 0.8

///***Useful Variables***///
  /// Ensure type is valid
  state.type = state.type == var.TYPE_BILATERAL || state.type == var.TYPE_UNILATERAL ? 
